import{z as s,x as d,o as E,c as B,q as i,j as r,D as e,d as o,s as A,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"创意与规模效应","description":"","frontmatter":{"title":"创意与规模效应","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gd-ideas-rivalry.md","filePath":"econ/gd-ideas-rivalry.md","lastUpdated":1791063341000}'),p={name:"econ/gd-ideas-rivalry.md"};function m(h,a,c,D,g,u){const t=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=i('<h1 id="创意与规模效应" tabindex="-1">创意与规模效应 <a class="header-anchor" href="#创意与规模效应" aria-label="Permalink to &quot;创意与规模效应&quot;">​</a></h1><div class="epigraph"><p>创意一次发现、处处使用——非竞争性把「多少人在想」变成增长的输入；但输入翻倍，不等于产出翻倍。</p><footer>—— 据 Romer, JPE 1990；Jones, &quot;R&amp;D-Based Models of Economic Growth&quot;, JPE 1995 整理</footer></div><p><a href="/econ/gd-endogenous-growth-deep">上一课</a>把品种扩张与创造性破坏解出均衡增长率：\\(g\\) 是研发劳动占比的增函数。这句话隐含规模效应——把更多人投入研究，就永久加速增长。缺口在数据：这个预言经不起时间序列。本课把创意的非竞争性本身当作对象，看它如何既生成规模效应、又如何在证据面前要求改写模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>美国从事研发的科学家与工程师人数，从二十世纪中叶到世纪末涨了数倍，联邦研发支出占 GDP 的份额也在六十年代见顶前翻倍；而<a href="/econ/solow-residual">索洛残差</a>的增速没有相应翻倍，反而走平。<span class="marginnote">『\\(g\\propto L_A\\)』代入数字：研究人数涨 4 倍，第一代模型预言增速也涨 4 倍——从年均 1% 变 4%，人均收入不到二十年翻一番。现实里增速几乎没动，这就是数据把模型打脸的分量。</span>若 \\(g\\propto L_A\\)，研究人数涨几倍，增长就该涨几倍——没有发生。缺口不在「研发重不重要」，在创意生产函数的形状：产出对存量 \\(A\\) 的弹性、对研究人数的弹性，哪一个被第一代模型写到了 1。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把上一课的 \\(\\dot{A}=\\delta L_A A\\) 改成 \\(\\dot{A}=\\delta L_A^\\lambda A^\\phi\\)，关键在 \\(\\phi\\lt1\\)：存量只部分溢出，站在肩膀上的高度有限，「找下一个创意」随存量变难。<span class="marginnote">\\(\\phi\\) 可以想象成「站上巨人肩膀后还能看到多远」：\\(\\phi=1\\) 是全额继承前辈的高度；\\(\\phi=0.5\\) 是每代只继承一半，剩下的要自己爬。\\(\\phi\\) 越小，旧创意对新创意的推力衰减越快，人海战术的回报越差。</span>平衡增长路径上解出 \\(g=\\lambda n/(1-\\phi)\\)：长期增长率由人口增长 \\(n\\) 驱动，研发补贴与人口规模只抬水平、不动斜率——这叫半内生增长。质量阶梯版本由 Young 1998 给出同族修正：新产品挤压旧产品，固定研究力量被摊薄在更多品种上，总加成不随人数线性放大。产业证据由 Bloom、Jones、Van Reenen 与 Webb 2020 汇齐：芯片、农业、医药三个域，维持同样的生产率增速，所需研究投入大约每十几年翻一倍——创意没有变容易找。Weitzman 1998 的组合视角把机制说穿：创意是旧创意的重组，搜索空间指数扩张与好组合越来越难找是同一件事的两面。</p>',7)),(E(),r(l,null,{default:e(()=>[A(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20POP%5B%22%E4%BA%BA%E5%8F%A3%E5%A2%9E%E9%95%BF%20n%22%5D%20--%3E%20LA%5B%22%E7%A0%94%E7%A9%B6%E4%BA%BA%E6%95%B0%22%5D%0A%20%20LA%20--%3E%20PROD%5B%22%E5%88%9B%E6%84%8F%E7%94%9F%E4%BA%A7%20%CF%86%3C1%22%5D%0A%20%20STOCK%5B%22%E5%88%9B%E6%84%8F%E5%AD%98%E9%87%8F%20A%22%5D%20--%3E%20PROD%0A%20%20PROD%20--%3E%20G%5B%22%E9%95%BF%E6%9C%9F%E5%A2%9E%E9%95%BF%E7%8E%87%20g%20%3D%20%CE%BBn%2F(1%E2%88%92%CF%86)%22%5D%0A%20%20SUB%5B%22%E7%A0%94%E5%8F%91%E8%A1%A5%E8%B4%B4%22%5D%20--%3E%20LEVEL%5B%22%E6%B0%B4%E5%B9%B3%E6%95%88%E5%BA%94%EF%BC%8C%E4%B8%8D%E5%8A%A8%20g%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[o("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"规模效应的根源是非竞争性：创意不因使用而折旧，全世界的存量对每个研究者都是公共输入，人口越多存量越大——这正是 \\(\\phi=1\\) 写下的世界。\\(\\phi\\lt1\\) 把存量推动力衰减到只剩 \\(n\\)：不是「人越多创意越多」失效，而是每份新增创意的平均难度同步上升。",-1)),(E(),r(l,null,{default:e(()=>[A(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20LA%5B%22%E7%A0%94%E7%A9%B6%E4%BA%BA%E6%95%B0%E7%BF%BB%E5%80%8D%22%5D%20--%3E%20D1%7B%22%CF%86%20%3D%201%3A%20%E5%AD%98%E9%87%8F%E5%85%A8%E9%A2%9D%E6%BA%A2%E5%87%BA%22%7D%0A%20%20LA%20--%3E%20D2%7B%22%CF%86%20%EF%BC%9C%201%3A%20%E8%82%A9%E8%86%80%E9%AB%98%E5%BA%A6%E6%9C%89%E9%99%90%22%7D%0A%20%20D1%20--%3E%20E1%5B%22g%20%E2%88%9D%20%E7%A0%94%E7%A9%B6%E4%BA%BA%E6%95%B0%20%E2%86%92%20%E8%A7%84%E6%A8%A1%E6%95%88%E5%BA%94%22%5D%0A%20%20D2%20--%3E%20E2%5B%22g%20%3D%20%CE%BBn%2F(1%E2%88%92%CF%86)%20%E2%86%92%20%E5%8F%AA%E9%9A%8F%E4%BA%BA%E5%8F%A3%E5%A2%9E%E9%95%BF%22%5D%0A%20%20E1%20--%3E%20P1%5B%22%E9%A2%84%E8%A8%80%3A%20%E5%A2%9E%E9%80%9F%E5%90%8C%E6%AD%A5%E7%BF%BB%E5%80%8D%22%5D%0A%20%20E2%20--%3E%20P2%5B%22%E9%A2%84%E8%A8%80%3A%20%E5%A2%9E%E9%80%9F%E4%B8%8D%E5%8F%98%2C%20%E5%8F%AA%E6%8A%AC%E6%B0%B4%E5%B9%B3%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">Weitzman 的组合直觉像做菜：创意是把旧食材（已有知识）重新搭配。食材种类翻倍，可能的搭配按平方级膨胀——搜索空间指数扩张，但好菜占比同步被稀释，找下一道好菜未必更容易。指数的机会与指数的难度是同一枚硬币。</span>政策对照随之改变：拿第一代模型去论证「补贴研发等于永久加速增长」，会被时间序列打脸；在半内生口径里补贴是水平效应，评价标准要换成折现的水平收益。能动斜率的按钮在别处：提高 \\(n\\) 之外的通道是让更多人接受前沿训练（<a href="/econ/human-capital-becker">人力资本</a>）与让市场更大、方向更偏（<a href="/econ/trade-growth">贸易与增长</a>、<a href="/econ/directed-technical-change">有向技术变化</a>）——它们通过 \\(\\lambda\\) 与市场规模改写激励，而不是套用「人数乘数」。</p><p><span class="marginnote">Bloom 等 2020 的读数不是「创新停滞」：摩尔定律仍在兑现，只是兑现同样增量所需的研究人数每十几年翻一倍。「变难」与「变慢」是两个命题。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>半内生模型把长期 \\(g\\) 钉在外生 \\(n\\) 上，也有反例：若干前沿经济体生育率长期下行，生产率增速未见同比例塌陷，说明 \\(n\\) 的传导并非机械。跨国比较不适用本课：追赶国的增长由技术扩散与赶超主导，不在前沿找创意，规模效应的公式套不上。<span class="marginnote">初学者容易把「补贴研发不动长期增速」套到所有国家。这条结论只适用于在技术前沿找创意的经济体；追赶国靠引进与扩散，人均增速可以长期高于前沿——把美国的公式套到后发国家，会把「追赶」误读成「创新」。</span>Bloom 等的证据限于产业层面，把它外推成全经济的「创意耗尽」是外推；Weitzman 的组合框架是组织直觉的透镜，不是可估的结构模型。上一课的两条政策结论里，「补贴动 \\(g\\)」被本课削掉，「套利条件决定激励」保留。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>规模效应是 \\(\\phi=1\\) 的产物；美国研发投入数倍增长而生产率增速平稳证伪了它。</li><li>\\(\\phi\\lt1\\) 给出半内生增长：\\(g=\\lambda n/(1-\\phi)\\)，长期增长由人口增长驱动。</li><li>研发补贴在此口径下是水平效应；动斜率的是人力资本、市场规模与创新方向。</li><li>「创意越来越难找」与「创新停滞」不是一回事，证据以产业层面为准。</li><li>追赶国靠扩散不在前沿找创意，本课公式不直接适用。</li><li>出处：Jones, <em>JPE</em> 1995；Young, <em>JPE</em> 1998；Weitzman, &quot;Recombinant Growth&quot;, <em>QJE</em> 1998；Bloom, Jones, Van Reenen and Webb, &quot;Are Ideas Getting Harder to Find?&quot;, <em>AER</em> 2020。</li></ul>',6))])}const f=s(p,[["render",m]]);export{_ as __pageData,f as default};
